import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, uniform, mix, vec3, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ============================================================================
  // 1. CREATE BASE PLANE GEOMETRY & MATERIAL
  // ============================================================================
  const geometry = new THREE.PlaneGeometry(2, 1.25);

  // Load image texture
  const material = new MeshBasicNodeMaterial();
  let textureLoaded = false;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.colorNode = texture(uniform(tex));
      material.needsUpdate = true;
      textureLoaded = true;
    });
  }

  const plane = new THREE.Mesh(geometry, material);

  // ============================================================================
  // 2. APPLY SCENE POSITION (adapter handles this, but explicit for safety)
  // ============================================================================
  if (config.scenePosition) {
    plane.position.set(
      config.scenePosition[0] ?? 0,
      config.scenePosition[1] ?? 0,
      config.scenePosition[2] ?? 0
    );
  }

  // ============================================================================
  // 3. INTERACTIVE STATE & HANDLERS
  // ============================================================================
  let isHovering = false;
  let pressTimeline = null;
  let hoverTimeline = null;

  const handlers = {
    pointerenter: () => {
      if (isHovering) return;
      isHovering = true;

      // Kill any existing hover timeline
      if (hoverTimeline) hoverTimeline.kill();

      // Rise-in: y +0.15 -> 0, power3.out, 0.7s (subtle lift)
      hoverTimeline = gsap.to(plane.position, {
        y: plane.position.y + 0.15,
        duration: 0.7,
        ease: 'power3.out'
      });
    },

    pointerleave: () => {
      if (!isHovering) return;
      isHovering = false;

      // Kill hover timeline and return to original position
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.to(plane.position, {
        y: config.scenePosition?.[1] ?? 0,
        duration: 0.5,
        ease: 'power2.out'
      });
    },

    pointerdown: () => {
      // Press-down: scale 0.97, 120ms, back.out
      if (pressTimeline) pressTimeline.kill();
      pressTimeline = gsap.to(plane.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out'
      });
    },

    pointerup: () => {
      // Return to scale 1.0
      if (pressTimeline) pressTimeline.kill();
      pressTimeline = gsap.to(plane.scale, {
        x: 1,
        y: 1,
        duration: 0.2,
        ease: 'back.out'
      });
    },

    click: () => {
      // Emit navigation event for journal selection
      ctx.emit('hub-journal.select', { nodeId: config.id });
    }
  };

  plane.userData.handlers = handlers;

  // ============================================================================
  // 4. STOCK BADGE DATA BINDING (from trpc.inventory.status.inStock)
  // ============================================================================
  plane.userData.stockBadge = {
    inStock: true, // default; will be bound by data source
    updateFromInventory: (status) => {
      plane.userData.stockBadge.inStock = status.inStock;
      // Optionally add visual feedback (e.g., opacity change, accent highlight)
      if (!status.inStock) {
        material.opacity = 0.6;
        material.needsUpdate = true;
      }
    }
  };

  // ============================================================================
  // 5. CLEANUP FUNCTION
  // ============================================================================
  plane.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    if (pressTimeline) pressTimeline.kill();
    geometry.dispose();
    material.dispose();
  };

  return plane;
}
